const b = $json.body || {};
const dpi = b.dpi || 300;
const model = b.model || "catmus-print";
if (!b.jobId || !b.callbackUrl || !b.pdfUrl || !b.runId) {
  throw new Error("invalid OCR payload: missing jobId/callbackUrl/pdfUrl/runId");
}
let fromPage = 1;
if (b.fromPage !== undefined && b.fromPage !== null) {
  const n = Number(b.fromPage);
  if (!Number.isInteger(n) || n < 1) {
    throw new Error("invalid OCR payload: fromPage must be a positive integer, got " + JSON.stringify(b.fromPage));
  }
  fromPage = n;
}

// SECURITY: every callback below (error/done/page/progress) carries the
// "OCR callback" bearer token. Only ever send it to the amadis app. Require
// https and match the host against an exact allowlist of hosts WE control
// (both under example.invalid, DNS we own). Failing fast HERE means no downstream
// Callback node runs, so the bearer is never sent to an attacker-controlled
// host (SSRF / token exfil). The host is parsed with a regex, NOT `new URL()`:
// the external JS task runner sandbox does not expose the `URL` global, so
// `new URL()` throws there and the catch masks the real reason.
const ALLOWED_CALLBACK_HOSTS = ["example.invalid", "example.invalid"];

const cbUrl = String(b.callbackUrl);
const m = /^https:\/\/([^/:?#]+)/i.exec(cbUrl);
if (!m) {
  throw new Error("refused callbackUrl: must be an https:// URL, got " + cbUrl);
}
const host = m[1].toLowerCase();
if (!ALLOWED_CALLBACK_HOSTS.includes(host)) {
  throw new Error("refused callbackUrl host '" + host + "': not in the amadis allowlist");
}

return [{ json: { jobId: b.jobId, pdfUrl: b.pdfUrl, callbackUrl: b.callbackUrl, fromPage, pagesTotal: b.pagesTotal ?? null, seed: b.seed || null, runId: b.runId, dpi, model } }];

const pages = $json.pages;
const v = $('Validate').first().json;
if (v.pagesTotal != null && v.pagesTotal !== pages) {
  throw new Error(`page count mismatch: OCR service reports ${pages} pages, amadis expected ${v.pagesTotal}`);
}
const out = [];
for (let page = v.fromPage; page <= pages; page++) {
  out.push({ json: { page, pdfUrl: v.pdfUrl, dpi: v.dpi, model: v.model, jobId: v.jobId, callbackUrl: v.callbackUrl, pagesTotal: pages, runId: v.runId } });
}
return out;

// A delivered "page" that carries seeded: true is a resume seam's
// reconstructed lookback context (see src/coherence.js), not a real OCR
// result — it must never be re-uploaded as a page callback.
function shouldSuppressDelivery(deliver) {
  return !deliver || deliver.seeded === true;
}

const d = $json.deliver;
const corrections = $json.corrections || [];
const isLast = $json.isLast === true;
const base = { jobId: $json.jobId, callbackUrl: $json.callbackUrl, pagesTotal: $json.pagesTotal, runId: $json.runId, isLast };
if (shouldSuppressDelivery(d)) return [{ json: { ...base, pagesDone: $json.pagesDone, pages: [] } }];
const bodyText = (d.lines || []).filter(l => (l.role || 'body') === 'body').map(l => l.text).join('\n');
return [{ json: { ...base, pagesDone: d.page, pages: [{ page: d.page, width: d.width, height: d.height, hocr: d.hocr, lines: d.lines, pageMeta: d.pageMeta, text: bodyText, corrections }] } }];

const sd = $getWorkflowStaticData('global');
const d = sd.amadisPrev || null;
sd.amadisPrev = null;
const v = $('Validate').first().json;
const m = sd.amadisMeta || {};
return [{ json: { jobId: v.jobId, callbackUrl: v.callbackUrl, pagesTotal: (m.pagesTotal != null ? m.pagesTotal : null), pagesDone: (d ? d.page : (m.pagesDone || 0)), deliver: d, isLast: true } }];

// Coherence-based header/footer resolution. Pure, no imports — paste-able into n8n Code nodes.

function _bodyLines(page) {
  return ((page && page.lines) || []).filter(l => (l.role || 'body') === 'body' && l.text && l.text.trim());
}
function firstBody(page) {
  const b = _bodyLines(page);
  return b.length ? b[0].text.trim() : '';
}
function lastBody(page) {
  const b = _bodyLines(page);
  return b.length ? b[b.length - 1].text.trim() : '';
}
function lineById(page, id) {
  return ((page && page.lines) || []).find(l => l.id === id) || null;
}
// Like firstBody, but skips a given line id — used so a header candidate that is
// still tagged role:'body' at resolution time doesn't count as its own NEXT.
function _firstBodyExcluding(page, excludeId) {
  const b = _bodyLines(page).filter(l => l.id !== excludeId);
  return b.length ? b[0].text.trim() : '';
}
// Like lastBody, but skips a given line id — used so a footer candidate that is
// still tagged role:'body' at resolution time doesn't count as its own PREV.
function _lastBodyExcluding(page, excludeId) {
  const b = _bodyLines(page).filter(l => l.id !== excludeId);
  return b.length ? b[b.length - 1].text.trim() : '';
}

const SYSTEM = [
  'Classify the CANDIDATE line from a scanned 16th-century French book. You are given three',
  'consecutive lines in reading order: PREV, CANDIDATE, NEXT (PREV or NEXT may be on the',
  'adjacent page). Body text flows continuously: lines break mid-word (often with a hyphen)',
  'or mid-sentence and continue on the following line.',
  '',
  'Decisive test: if removing CANDIDATE lets PREV and NEXT read as one continuous passage,',
  'then CANDIDATE is the interrupting header/footer. If CANDIDATE is itself part of that flow,',
  'it is body.',
  '',
  'Rules:',
  '- "body" is the default. If CANDIDATE continues the sentence or word begun in PREV, or if',
  '  NEXT continues the sentence or word begun in CANDIDATE, then CANDIDATE is ALWAYS body,',
  '  no matter how short and no matter its position on the page.',
  '- "header": a self-contained running head or section title at the top of a page (e.g. a',
  '  book/part title such as "DU SECOND LIVRE", or a page number). It does NOT continue PREV.',
  '- "footer": a self-contained catchword, printer signature, or page number at the foot of a',
  '  page. NEXT does NOT continue from it.',
  'A footer/catchword/signature/page-number is SHORT (a single word, a signature like "A ij", or a number); a full line of running prose is never a footer.',
  'Ignore OCR noise: a meaningless one/two-character fragment that breaks the flow is body.',
  'When unsure, answer "body".',
  'Respond with ONLY a JSON object:',
  '{"role":"header"|"footer"|"body","kind":"runningHead"|"pageNumber"|"catchword"|null}',
].join('\n');

function buildCoherencePrompt(candidate, prev, next, position) {
  const user = JSON.stringify({ position, PREV: prev || '', CANDIDATE: candidate || '', NEXT: next || '' }, null, 2);
  return { system: SYSTEM, user };
}

// DEFAULT 'body' when unparseable — safety bias: keep the line in the transcription.
function parseVerdict(text) {
  const fallback = { role: 'body', kind: null };
  if (!text) return fallback;
  const m = String(text).match(/\{[\s\S]*\}/);
  if (!m) return fallback;
  let obj;
  try { obj = JSON.parse(m[0]); } catch (e) { return fallback; }
  if (obj.role === 'header' || obj.role === 'footer' || obj.role === 'body') {
    const kind = ['runningHead', 'pageNumber', 'catchword'].includes(obj.kind) ? obj.kind : null;
    return { role: obj.role, kind };
  }
  return fallback;
}

function resolveRequests(prevPage, curPage, isFirst) {
  const reqs = [];
  // Header of the CURRENT page: needs prev page's last body line + this page's first body line.
  const topId = curPage && curPage.pageMeta && curPage.pageMeta.ambiguous && curPage.pageMeta.ambiguous.top;
  if (topId && !isFirst && prevPage) {
    const cand = lineById(curPage, topId);
    const p = buildCoherencePrompt(cand ? cand.text : '', lastBody(prevPage), _firstBodyExcluding(curPage, topId), 'top');
    reqs.push({ target: 'cur-header', pageRef: 'cur', candidateId: topId, position: 'top', system: p.system, user: p.user });
  }
  // Footer of the PREVIOUS page: needs prev page's last body line (excluding the
  // candidate itself) + this page's first body line.
  const botId = prevPage && prevPage.pageMeta && prevPage.pageMeta.ambiguous && prevPage.pageMeta.ambiguous.bottom;
  if (botId && curPage) {
    const cand = lineById(prevPage, botId);
    const p = buildCoherencePrompt(cand ? cand.text : '', _lastBodyExcluding(prevPage, botId), firstBody(curPage), 'bottom');
    reqs.push({ target: 'prev-footer', pageRef: 'prev', candidateId: botId, position: 'bottom', system: p.system, user: p.user });
  }
  return reqs;
}

function applyVerdict(page, candidateId, verdict, position) {
  const line = lineById(page, candidateId);
  if (!line) return;
  const v = verdict || { role: 'body', kind: null };
  let role = v.role;
  if (position === 'top' && role === 'footer') role = 'body';      // a top line is never a footer
  if (position === 'bottom' && role === 'header') role = 'body';   // a bottom line is never a header
  if (role === 'header') {
    line.role = 'header';
    page.pageMeta.header = { text: line.text };
  } else if (role === 'footer') {
    line.role = 'footer';
    const kind = v.kind === 'pageNumber' || v.kind === 'catchword' ? v.kind : 'signature';
    line.footerKind = kind;
    page.pageMeta.footer = { text: line.text, kind };
  } else {
    line.role = 'body';
  }
  // Clear whichever ambiguous slot this candidate occupied, keyed by id (not by the
  // verdict role) so a cross-role verdict can't clear a different candidate's slot.
  if (page.pageMeta.ambiguous) {
    if (page.pageMeta.ambiguous.top === candidateId) page.pageMeta.ambiguous.top = null;
    if (page.pageMeta.ambiguous.bottom === candidateId) page.pageMeta.ambiguous.bottom = null;
  }
}

