// LLM low-confidence correction. Pure, no imports — paste-able into n8n Code nodes.

const LOWCONF_THRESHOLD = 0.6;
const MARK_OPEN = '⟦';
const MARK_CLOSE = '⟧';

// [{word,start,end}] for each maximal non-whitespace run in s.
function _wordRanges(s) {
  const out = [];
  const re = /\S+/g;
  let m;
  while ((m = re.exec(s)) !== null) out.push({ word: m[0], start: m.index, end: m.index + m[0].length });
  return out;
}

// Body line → suspect word spans in line.text coordinates.
// charConfidences is aligned to textRaw; line.text differs from textRaw only by a
// prepended drop-cap letter on the first body line, so a constant length offset maps
// raw indices into text. If that clean offset does not hold, fall back to locating the
// word substring in text; if it cannot be located, the word is skipped.
function suspectSpans(line, threshold) {
  const t = (threshold == null) ? LOWCONF_THRESHOLD : threshold;
  const text = line && typeof line.text === 'string' ? line.text : '';
  const raw = line && typeof line.textRaw === 'string' ? line.textRaw : '';
  const conf = line && Array.isArray(line.charConfidences) ? line.charConfidences : null;
  if (!text || !raw || !conf || conf.length === 0) return [];
  if (text.indexOf(MARK_OPEN) !== -1 || text.indexOf(MARK_CLOSE) !== -1) return [];
  const offset = text.length - raw.length;
  const cleanOffset = offset >= 0 && text.slice(offset) === raw;
  const spans = [];
  for (const w of _wordRanges(raw)) {
    let minConf = Infinity, suspect = false;
    for (let i = w.start; i < w.end; i++) {
      const cf = i < conf.length ? conf[i] : 1;
      if (cf < minConf) minConf = cf;
      if (cf < t) suspect = true;
    }
    if (!suspect) continue;
    let start, end;
    if (cleanOffset) { start = w.start + offset; end = w.end + offset; }
    else { const idx = text.indexOf(w.word); if (idx < 0) continue; start = idx; end = idx + w.word.length; }
    spans.push({ word: text.slice(start, end), start, end, minConf });
  }
  spans.sort((a, b) => a.start - b.start);
  return spans;
}

function markText(text, spans) {
  if (!spans || spans.length === 0) return text;
  const sorted = spans.slice().sort((a, b) => a.start - b.start);
  let out = '', pos = 0;
  for (const s of sorted) { out += text.slice(pos, s.start) + MARK_OPEN + text.slice(s.start, s.end) + MARK_CLOSE; pos = s.end; }
  return out + text.slice(pos);
}

const CORRECTION_SYSTEM = [
  'You are correcting OCR output from a printed 16th-century French book.',
  'You are given three consecutive lines: PREV, LINE, NEXT. Only LINE may be edited.',
  'In LINE, suspect character spans are wrapped in ⟦ ⟧ markers. These, and ONLY these, may',
  'contain OCR misreads to fix.',
  'Rules — follow ALL of them exactly:',
  '- Change characters ONLY inside the ⟦ ⟧ markers. Everything outside the markers must be',
  '  returned byte-for-byte identical.',
  '- Keep the ⟦ ⟧ markers in your answer, around the (possibly corrected) spans.',
  '- Fix only genuine OCR misreads (letter shapes confused: long-s/f, u/n, c/e, etc.).',
  '- Do NOT modernize or normalize spelling. 16th-century French spelling is CORRECT as-is;',
  '  preserve archaic forms, accents, and abbreviations. When unsure, leave the span unchanged.',
  'Respond with ONLY a JSON object: {"corrected":"<the LINE with markers preserved>"}',
].join('\n');

function buildCorrectionPrompt(markedText, prevBody, nextBody) {
  const user = JSON.stringify({ PREV: prevBody || '', LINE: markedText, NEXT: nextBody || '' }, null, 2);
  return { system: CORRECTION_SYSTEM, user };
}

// Correctable lines are body prose AND rubric titles: role is only metadata, the
// title text is OCR of the same 16th-c. print and benefits from the same low-conf
// correction. Headers/footers (page numbers, catchwords, watermark) stay out.
const CORRECTABLE_ROLES = new Set(['body', 'title']);

function correctionRequests(page, threshold) {
  const lines = (page && page.lines) || [];
  const corr = lines.filter(l => CORRECTABLE_ROLES.has(l.role || 'body') && typeof l.text === 'string' && l.text.trim());
  const reqs = [];
  for (let i = 0; i < corr.length; i++) {
    const line = corr[i];
    const spans = suspectSpans(line, threshold);
    if (!spans.length) continue;
    const p = buildCorrectionPrompt(markText(line.text, spans), i > 0 ? corr[i - 1].text : '', i < corr.length - 1 ? corr[i + 1].text : '');
    reqs.push({ lineId: line.id, original: line.text, spans, system: p.system, user: p.user });
  }
  return reqs;
}

function parseCorrected(text) {
  if (!text) return null;
  const m = String(text).match(/\{[\s\S]*\}/);
  if (!m) return null;
  let obj;
  try { obj = JSON.parse(m[0]); } catch (e) { return null; }
  return typeof obj.corrected === 'string' ? obj.corrected : null;
}

// Split a marked string into {outside:[n+1], inside:[n]}, or null if unbalanced/nested.
function _splitMarked(s) {
  const outside = [], inside = [];
  let i = 0, buf = '';
  while (i < s.length) {
    const ch = s[i];
    if (ch === MARK_OPEN) {
      outside.push(buf); buf = ''; i++;
      let inner = '';
      while (i < s.length && s[i] !== MARK_CLOSE) { if (s[i] === MARK_OPEN) return null; inner += s[i]; i++; }
      if (i >= s.length) return null;
      inside.push(inner); i++;
    } else if (ch === MARK_CLOSE) { return null; }
    else { buf += ch; i++; }
  }
  outside.push(buf);
  return { outside, inside };
}

// Marker-anchored guard: only inside-marker characters may change; everything outside
// must be byte-identical to the original's outside-marker text. Any violation → revert.
function acceptMarkerAnchored(original, spans, correctedMarked) {
  const revert = { text: original, accepted: false, insides: [] };
  if (typeof correctedMarked !== 'string') return revert;
  const got = _splitMarked(correctedMarked);
  if (!got) return revert;
  if (got.inside.length !== (spans ? spans.length : 0)) return revert;
  const exp = _splitMarked(markText(original, spans));
  if (!exp || exp.outside.length !== got.outside.length) return revert;
  for (let k = 0; k < exp.outside.length; k++) if (exp.outside[k] !== got.outside[k]) return revert;
  let text = '';
  for (let k = 0; k < got.inside.length; k++) text += got.outside[k] + got.inside[k];
  text += got.outside[got.outside.length - 1];
  return { text, accepted: true, insides: got.inside };
}

function wordDiff(lineId, spans, insides) {
  const out = [];
  for (let i = 0; i < spans.length; i++) {
    if (insides[i] !== spans[i].word) {
      out.push({ lineId, original: spans[i].word, corrected: insides[i], kind: 'llm-lowconf', confidence: spans[i].minConf });
    }
  }
  return out;
}

// Guard + apply for one line. spans MUST have been computed from the current line.text.
function applyLineCorrection(line, correctedMarked, spans) {
  const res = acceptMarkerAnchored(line.text, spans, correctedMarked);
  if (!res.accepted) return [];
  const entries = wordDiff(line.id, spans, res.insides);
  line.text = res.text;
  return entries;
}

// ---- Prep correction: compute per-line requests on the delivered page ----
const sd = $getWorkflowStaticData('global');
const meta = $json;
const deliver = meta.deliver || null;
const isLast = meta.isLast === true;
const reqs = deliver ? correctionRequests(deliver, LOWCONF_THRESHOLD) : [];
sd.amadisCorr = reqs.map(r => ({ lineId: r.lineId, spans: r.spans }));
sd.amadisCorrCtx = { jobId: meta.jobId, callbackUrl: meta.callbackUrl, pagesTotal: meta.pagesTotal, pagesDone: meta.pagesDone, deliver, isLast };
return [{ json: {
  reqs: reqs.map(r => ({ system_prompt: r.system, user_prompt: r.user })),
  jobId: meta.jobId, callbackUrl: meta.callbackUrl, pagesTotal: meta.pagesTotal, pagesDone: meta.pagesDone,
  deliver, isLast, corrections: []
} }];

// LLM low-confidence correction. Pure, no imports — paste-able into n8n Code nodes.

const LOWCONF_THRESHOLD = 0.6;
const MARK_OPEN = '⟦';
const MARK_CLOSE = '⟧';

// [{word,start,end}] for each maximal non-whitespace run in s.
function _wordRanges(s) {
  const out = [];
  const re = /\S+/g;
  let m;
  while ((m = re.exec(s)) !== null) out.push({ word: m[0], start: m.index, end: m.index + m[0].length });
  return out;
}

// Body line → suspect word spans in line.text coordinates.
// charConfidences is aligned to textRaw; line.text differs from textRaw only by a
// prepended drop-cap letter on the first body line, so a constant length offset maps
// raw indices into text. If that clean offset does not hold, fall back to locating the
// word substring in text; if it cannot be located, the word is skipped.
function suspectSpans(line, threshold) {
  const t = (threshold == null) ? LOWCONF_THRESHOLD : threshold;
  const text = line && typeof line.text === 'string' ? line.text : '';
  const raw = line && typeof line.textRaw === 'string' ? line.textRaw : '';
  const conf = line && Array.isArray(line.charConfidences) ? line.charConfidences : null;
  if (!text || !raw || !conf || conf.length === 0) return [];
  if (text.indexOf(MARK_OPEN) !== -1 || text.indexOf(MARK_CLOSE) !== -1) return [];
  const offset = text.length - raw.length;
  const cleanOffset = offset >= 0 && text.slice(offset) === raw;
  const spans = [];
  for (const w of _wordRanges(raw)) {
    let minConf = Infinity, suspect = false;
    for (let i = w.start; i < w.end; i++) {
      const cf = i < conf.length ? conf[i] : 1;
      if (cf < minConf) minConf = cf;
      if (cf < t) suspect = true;
    }
    if (!suspect) continue;
    let start, end;
    if (cleanOffset) { start = w.start + offset; end = w.end + offset; }
    else { const idx = text.indexOf(w.word); if (idx < 0) continue; start = idx; end = idx + w.word.length; }
    spans.push({ word: text.slice(start, end), start, end, minConf });
  }
  spans.sort((a, b) => a.start - b.start);
  return spans;
}

function markText(text, spans) {
  if (!spans || spans.length === 0) return text;
  const sorted = spans.slice().sort((a, b) => a.start - b.start);
  let out = '', pos = 0;
  for (const s of sorted) { out += text.slice(pos, s.start) + MARK_OPEN + text.slice(s.start, s.end) + MARK_CLOSE; pos = s.end; }
  return out + text.slice(pos);
}

const CORRECTION_SYSTEM = [
  'You are correcting OCR output from a printed 16th-century French book.',
  'You are given three consecutive lines: PREV, LINE, NEXT. Only LINE may be edited.',
  'In LINE, suspect character spans are wrapped in ⟦ ⟧ markers. These, and ONLY these, may',
  'contain OCR misreads to fix.',
  'Rules — follow ALL of them exactly:',
  '- Change characters ONLY inside the ⟦ ⟧ markers. Everything outside the markers must be',
  '  returned byte-for-byte identical.',
  '- Keep the ⟦ ⟧ markers in your answer, around the (possibly corrected) spans.',
  '- Fix only genuine OCR misreads (letter shapes confused: long-s/f, u/n, c/e, etc.).',
  '- Do NOT modernize or normalize spelling. 16th-century French spelling is CORRECT as-is;',
  '  preserve archaic forms, accents, and abbreviations. When unsure, leave the span unchanged.',
  'Respond with ONLY a JSON object: {"corrected":"<the LINE with markers preserved>"}',
].join('\n');

function buildCorrectionPrompt(markedText, prevBody, nextBody) {
  const user = JSON.stringify({ PREV: prevBody || '', LINE: markedText, NEXT: nextBody || '' }, null, 2);
  return { system: CORRECTION_SYSTEM, user };
}

// Correctable lines are body prose AND rubric titles: role is only metadata, the
// title text is OCR of the same 16th-c. print and benefits from the same low-conf
// correction. Headers/footers (page numbers, catchwords, watermark) stay out.
const CORRECTABLE_ROLES = new Set(['body', 'title']);

function correctionRequests(page, threshold) {
  const lines = (page && page.lines) || [];
  const corr = lines.filter(l => CORRECTABLE_ROLES.has(l.role || 'body') && typeof l.text === 'string' && l.text.trim());
  const reqs = [];
  for (let i = 0; i < corr.length; i++) {
    const line = corr[i];
    const spans = suspectSpans(line, threshold);
    if (!spans.length) continue;
    const p = buildCorrectionPrompt(markText(line.text, spans), i > 0 ? corr[i - 1].text : '', i < corr.length - 1 ? corr[i + 1].text : '');
    reqs.push({ lineId: line.id, original: line.text, spans, system: p.system, user: p.user });
  }
  return reqs;
}

function parseCorrected(text) {
  if (!text) return null;
  const m = String(text).match(/\{[\s\S]*\}/);
  if (!m) return null;
  let obj;
  try { obj = JSON.parse(m[0]); } catch (e) { return null; }
  return typeof obj.corrected === 'string' ? obj.corrected : null;
}

// Split a marked string into {outside:[n+1], inside:[n]}, or null if unbalanced/nested.
function _splitMarked(s) {
  const outside = [], inside = [];
  let i = 0, buf = '';
  while (i < s.length) {
    const ch = s[i];
    if (ch === MARK_OPEN) {
      outside.push(buf); buf = ''; i++;
      let inner = '';
      while (i < s.length && s[i] !== MARK_CLOSE) { if (s[i] === MARK_OPEN) return null; inner += s[i]; i++; }
      if (i >= s.length) return null;
      inside.push(inner); i++;
    } else if (ch === MARK_CLOSE) { return null; }
    else { buf += ch; i++; }
  }
  outside.push(buf);
  return { outside, inside };
}

// Marker-anchored guard: only inside-marker characters may change; everything outside
// must be byte-identical to the original's outside-marker text. Any violation → revert.
function acceptMarkerAnchored(original, spans, correctedMarked) {
  const revert = { text: original, accepted: false, insides: [] };
  if (typeof correctedMarked !== 'string') return revert;
  const got = _splitMarked(correctedMarked);
  if (!got) return revert;
  if (got.inside.length !== (spans ? spans.length : 0)) return revert;
  const exp = _splitMarked(markText(original, spans));
  if (!exp || exp.outside.length !== got.outside.length) return revert;
  for (let k = 0; k < exp.outside.length; k++) if (exp.outside[k] !== got.outside[k]) return revert;
  let text = '';
  for (let k = 0; k < got.inside.length; k++) text += got.outside[k] + got.inside[k];
  text += got.outside[got.outside.length - 1];
  return { text, accepted: true, insides: got.inside };
}

function wordDiff(lineId, spans, insides) {
  const out = [];
  for (let i = 0; i < spans.length; i++) {
    if (insides[i] !== spans[i].word) {
      out.push({ lineId, original: spans[i].word, corrected: insides[i], kind: 'llm-lowconf', confidence: spans[i].minConf });
    }
  }
  return out;
}

// Guard + apply for one line. spans MUST have been computed from the current line.text.
function applyLineCorrection(line, correctedMarked, spans) {
  const res = acceptMarkerAnchored(line.text, spans, correctedMarked);
  if (!res.accepted) return [];
  const entries = wordDiff(line.id, spans, res.insides);
  line.text = res.text;
  return entries;
}

// ---- Apply corrections: zip LLM answers with stored requests, mutate deliver body lines ----
const sd = $getWorkflowStaticData('global');
const outs = $input.all();
const corr = sd.amadisCorr || [];
const ctx = sd.amadisCorrCtx || {};
const deliver = ctx.deliver || null;
const corrections = [];
if (deliver) {
  for (let i = 0; i < corr.length; i++) {
    const text = (outs[i] && outs[i].json && (outs[i].json.answer || outs[i].json.output || outs[i].json.text || '')) || '';
    const cRec = corr[i];
    const line = (deliver.lines || []).find(l => l.id === cRec.lineId);
    if (!line) continue;
    const parsed = parseCorrected(text);
    if (parsed === null) continue;
    for (const e of applyLineCorrection(line, parsed, cRec.spans)) corrections.push(e);
  }
}
return [{ json: { jobId: ctx.jobId, callbackUrl: ctx.callbackUrl, pagesTotal: ctx.pagesTotal, pagesDone: ctx.pagesDone, deliver, isLast: !!ctx.isLast, corrections } }];

// Resets the cross-page coherence lookback before every run (fresh or
// resumed): a resumed run never passes through cur.page === 1, the only
// place Prep coherence nulls this buffer itself, so without this it would
// run with leftover state from whatever run touched this workflow last.
// Must return the Validate item unchanged (Page count reads $json.pdfUrl
// next) — this node only ever adds to workflow static data, never to $json.
const sd = $getWorkflowStaticData('global');
delete sd.amadisPrev;
delete sd.amadisDeliver;
delete sd.amadisReqs;
delete sd.amadisMeta;
const v = $json;
if (v.seed) {
  sd.amadisPrev = { page: v.seed.page, lines: v.seed.lines, pageMeta: v.seed.pageMeta, seeded: true };
}
return [{ json: v }];
